def _read_wb_live_session_state(
    *,
    live_path=WB_LIVE_SESSION_FILE,
    checkpoint_path=WB_LIVE_SESSION_CHECKPOINT_FILE,
    legacy_path=WB_LIVE_SESSION_LEGACY_FILE,
    now_ts=None,
):
    """Liest Live-RAM, danach Restart-Checkpoint und zuletzt den Altpfad."""

    current_ts = time.time() if now_ts is None else float(now_ts)
    candidates = (
        (live_path, 300.0),
        (checkpoint_path, 6 * 3600.0),
        (legacy_path, 300.0),
    )
    for path, max_age_s in candidates:
        try:
            if not path or not os.path.isfile(path):
                continue
            age_s = max(0.0, current_ts - os.path.getmtime(path))
            if age_s > max_age_s:
                continue
            with open(path, "r", encoding="utf-8") as handle:
                payload = json.load(handle)
            if isinstance(payload, dict) and payload.get("source") == "rscp":
                return payload, path
        except Exception:
            continue
    return {}, ""


def _write_wb_live_session(path, payload):
    tmp = f"{path}.tmp.{os.getpid()}.{time.monotonic_ns()}"
    try:
        os.makedirs(os.path.dirname(path), exist_ok=True)
        with open(tmp, "w", encoding="utf-8") as handle:
            json.dump(payload, handle, ensure_ascii=False, separators=(",", ":"))
        os.replace(tmp, path)
        try:
            os.chmod(path, 0o664)
        except OSError:
            pass
        return True
    except Exception:
        try:
            if os.path.exists(tmp):
                os.remove(tmp)
        except Exception:
            pass
        return False


def _persist_wb_session_checkpoint(
    payload,
    runtime_state,
    *,
    path=WB_LIVE_SESSION_CHECKPOINT_FILE,
    now_ts=None,
    force=False,
):
    """Sichert Sitzungsübergänge sofort, Zählerfortschritt höchstens alle 120 s."""

    current_ts = time.time() if now_ts is None else float(now_ts)
    current_power = float((payload or {}).get("power_w", 0) or 0)
    last_power = float(runtime_state.get("last_power_w", 0) or 0)
    stop_event = (last_power > 0.0 and current_power == 0.0)

    car_connected = bool((payload or {}).get("car_connected", False))
    signature = (
        car_connected,
        (payload or {}).get("session_start_ts"),
    )
    last_write_ts = float(runtime_state.get("last_write_ts", 0.0) or 0.0)
    elapsed_s = current_ts - last_write_ts
    clock_reset = (last_write_ts > 0.0 and elapsed_s < 0.0)
    heartbeat_due = (
        clock_reset
        or (
            car_connected
            and (
                last_write_ts <= 0.0
                or elapsed_s >= WB_LIVE_SESSION_CHECKPOINT_HEARTBEAT_S
            )
        )
    )
    if not (
        force
        or stop_event
        or signature != runtime_state.get("signature")
        or heartbeat_due
    ):
        runtime_state["last_power_w"] = current_power
        return False
    checkpoint = dict(payload or {})
    checkpoint["schema_version"] = "wb_native_session_checkpoint_v1"
    checkpoint["checkpoint_ts"] = current_ts
    if not _write_wb_live_session(path, checkpoint):
        return False
    runtime_state["signature"] = signature
    runtime_state["last_write_ts"] = current_ts
    runtime_state["last_power_w"] = current_power
    return True


def _car_soc_source_rule_confirmed(source):
    text = str(source or "").strip().lower()
    if not text or text in UNCONFIRMED_CAR_SOC_SOURCES:
        return False
    if text.startswith("wallbox_estimated_from_"):
        return _car_soc_source_rule_confirmed(text[len("wallbox_estimated_from_"):])
    if text.startswith("wallbox_estimated"):
        return False
    if text in CONFIRMED_CAR_SOC_MANUAL_SOURCES or text in CONFIRMED_CAR_SOC_DIRECT_SOURCES:
        return True
    return any(token in text for token in CONFIRMED_CAR_SOC_KEYWORDS)


def _car_soc_rule_confirmed(status):
    if not isinstance(status, dict):
        return False
    if bool(status.get("car_soc_rule_confirmed", False)):
        return True
    return _car_soc_source_rule_confirmed(status.get("car_soc_source"))


def _openwb_primary_chargemode_key(value):
    text = str(value or "").strip().lower()
    if text in ("instant", "instant_charging"):
        return "instant"
    if text in ("pv", "pv_charging"):
        return "pv"
    if text in ("stop", "stopped"):
        return "stop"
    return text


def _openwb_primary_grid_phase_warning(
    status,
    c_data=None,
    *,
    public_mode=0,
    cap_amp=0,
    scheduled_slot_active=False,
    mode5_grid_allowed=False,
    price_boost_active=False,
    vehicle_max_phases=0,
):
    """Diagnostic only: openWB Primary grid charging may be stuck at 1p."""
    st = status if isinstance(status, dict) else {}
    box = c_data if isinstance(c_data, dict) else {}
    charger = box.get("charger")
    charger_class = charger.__class__.__name__ if charger is not None else str(box.get("_charger_class_name", "") or "")
    primary_openwb = bool(
        charger_class == "OpenWBCharger"
        and (
            getattr(charger, "primary_mode_enabled", False)
            or str(st.get("effective_role") or st.get("configured_role") or "").lower().startswith("primary")
            or str(st.get("api_surface") or "").lower().startswith("openwb_primary")
        )
    )
    if not primary_openwb:
        return None

    mode = normalize_wb_mode(public_mode)
    grid_intent = bool(
        mode == MODE_PRICE
        or scheduled_slot_active
        or mode5_grid_allowed
        or price_boost_active
    )
    if not grid_intent or not _wb_status_real_charging(st):
        return None

    target_amp = max(
        _cfg_float(box.get("current_set_amp"), 0.0),
        _cfg_float(st.get("last_command_amp"), 0.0),
        _cfg_float(st.get("instant_charging_current"), 0.0),
        _cfg_float(st.get("amp"), 0.0),
        _cfg_float(cap_amp, 0.0),
    )
    if target_amp < 10.0:
        return None

    real_power_w = max(0.0, abs(_wb_status_real_power(st)))
    if real_power_w < 500.0:
        return None

    actual_phases = _valid_phase_count(st.get("phases_in_use"), 0)
    if not actual_phases:
        actual_phases = _valid_phase_count(st.get("phase_actual_phases"), 0)
    if not actual_phases:
        phase_powers = [
            abs(_cfg_float(st.get("phase_power_l1_w"), 0.0)),
            abs(_cfg_float(st.get("phase_power_l2_w"), 0.0)),
            abs(_cfg_float(st.get("phase_power_l3_w"), 0.0)),
        ]
        active_phase_count = sum(1 for value in phase_powers if value > 100.0)
        actual_phases = active_phase_count if active_phase_count in (1, 2, 3) else 0

    expected_3p_w = target_amp * 230.0 * 3.0
    low_vs_3p = bool(expected_3p_w > 0.0 and real_power_w < expected_3p_w * 0.55)
    one_phase_hint = bool(actual_phases == 1 or (actual_phases <= 0 and low_vs_3p))
    if not one_phase_hint:
        return None

    vehicle_phases = _valid_phase_count(vehicle_max_phases, 0) or _valid_phase_count(st.get("phase_vehicle_max_phases"), 0)
    connected_phases = _valid_phase_count(st.get("connected_phases"), 0) or _valid_phase_count(st.get("phase_cable_phases"), 0)
    capable_hint = "Fahrzeug/Anschluss wirkt 3p-fähig." if max(vehicle_phases, connected_phases) >= 3 else "Wenn Fahrzeug und Installation 3p können,"
    phase_text = "%dp" % actual_phases if actual_phases > 0 else "Phasen unklar"
    reason = (
        "openWB Primary Netzladen: %.1f A angefordert, real %.0f W (%s). %s "
        "E3DC-Control gibt Sofortladen/Strom vor, erzwingt aber keine Phasenumschaltung; "
        "openWB-Sofortladen, Phasenautomatik und Fahrzeugprofil prüfen."
    ) % (target_amp, real_power_w, phase_text, capable_hint)
    return {
        "state": "Primary 1p",
        "state_level": "warning",
        "state_reason": reason,
        "control_status": "openwb_primary_grid_phase_warning",
        "control_label": "Primary lädt 1-phasig",
        "control_detail": reason,
        "control_level": "warning",
        "openwb_primary_grid_phase_warning": True,
        "openwb_primary_grid_phase_warning_reason": reason,
        "openwb_primary_grid_target_amp": round(target_amp, 1),
        "openwb_primary_grid_actual_power_w": round(real_power_w, 1),
        "openwb_primary_grid_actual_phases": int(actual_phases or 0),
        "openwb_primary_grid_expected_3p_w": round(expected_3p_w, 1),
        "openwb_primary_grid_vehicle_phases": int(vehicle_phases or 0),
        "openwb_primary_grid_connected_phases": int(connected_phases or 0),
    }


def _wallbox_vehicle_under_acceptance_warning(
    status,
    c_data=None,
    *,
    cap_amp=0,
    detected_phases=0,
    min_amp=6,
):
    """Diagnostic only: EVSE offers a clear current, vehicle takes much less."""
    st = status if isinstance(status, dict) else {}
    box = c_data if isinstance(c_data, dict) else {}
    candidate_key = "_vehicle_under_acceptance_candidate"
    transition = box.get("_wallbox_phase_transition_reservation")
    phase_sequence = box.get("_openwb_pro_phase_sequence")
    recovery = box.get("_openwb_pro_phase_recovery_hold")
    ramp = box.get("_ramp_contract")
    transition_active = bool(
        (isinstance(transition, dict) and transition.get("active", False))
        or (isinstance(phase_sequence, dict) and phase_sequence)
        or (isinstance(recovery, dict) and recovery.get("active", False))
        or _cfg_float(box.get("_openwb_pro_phase_wait_until"), 0.0) > time.time()
    )
    status_fresh = bool(
        st
        and st.get("driver_status_valid", True)
        and not st.get("driver_status_stale", False)
        and not st.get("driver_status_degraded", False)
        and not st.get("driver_status_glitch", False)
    )
    if (
        not status_fresh
        or not _wb_status_real_charging(st)
        or st.get("cp_interrupt_isactive") not in (False, 0, None)
        or transition_active
        or (isinstance(ramp, dict) and ramp.get("limited", False))
    ):
        box.pop(candidate_key, None)
        return None

    # Nur der frische EVSE-Readback ist ein reales Stromangebot. Policydeckel,
    # Sollstrom und letzter Befehl sind keine Aussage darüber, was die Wallbox
    # dem Fahrzeug in diesem Moment tatsächlich anbietet.
    target_amp = max(
        _cfg_float(st.get("offered_current_raw"), 0.0),
        _cfg_float(st.get("offered_current"), 0.0),
        _cfg_float(st.get("evse_current"), 0.0),
        _cfg_float(st.get("amp"), 0.0),
    )
    min_offer_amp = max(10.0, _cfg_float(min_amp, 6.0) + 3.0)
    if target_amp < min_offer_amp:
        box.pop(candidate_key, None)
        return None

    target_phases = _valid_phase_count(st.get("phases_target"), 0)
    if not target_phases:
        target_phases = _valid_phase_count(st.get("phase_effective_phases"), 0)
    if not target_phases:
        target_phases = _valid_phase_count(st.get("wallbox_phases"), 0)
    if not target_phases:
        target_phases = _valid_phase_count(detected_phases, 0)
    if not target_phases:
        target_phases = _valid_phase_count(st.get("number_phases"), 0)
    target_phases = max(1, target_phases or 1)

    real_power_w = max(0.0, abs(_wb_status_real_power(st)))
    expected_power_w = target_amp * 230.0 * target_phases
    if real_power_w < 500.0 or expected_power_w < 4500.0:
        box.pop(candidate_key, None)
        return None

    shortfall_w = expected_power_w - real_power_w
    accepted_ratio = real_power_w / expected_power_w if expected_power_w > 0.0 else 1.0
    if not (accepted_ratio < 0.65 and shortfall_w >= max(1500.0, expected_power_w * 0.25)):
        box.pop(candidate_key, None)
        return None

    sample_ts = _cfg_float(
        st.get("driver_status_last_sample_ts", st.get("sample_ts", 0.0)),
        0.0,
    )
    signature = "%0.2f:%d" % (target_amp, target_phases)
    candidate = box.get(candidate_key)
    if not isinstance(candidate, dict) or candidate.get("signature") != signature:
        box[candidate_key] = {
            "signature": signature,
            "first_sample_ts": sample_ts,
            "last_sample_ts": sample_ts,
            "samples": 1,
        }
        return None
    last_sample_ts = _cfg_float(candidate.get("last_sample_ts"), 0.0)
    first_sample_ts = _cfg_float(candidate.get("first_sample_ts"), sample_ts)
    if sample_ts <= 0.0 or sample_ts <= last_sample_ts:
        return None
    candidate["last_sample_ts"] = sample_ts
    candidate["samples"] = int(candidate.get("samples", 1) or 1) + 1
    if sample_ts - first_sample_ts < 45.0:
        return None

    actual_phases = _valid_phase_count(st.get("phases_in_use"), 0)
    if not actual_phases:
        actual_phases = _valid_phase_count(st.get("phase_actual_phases"), 0)
    if not actual_phases:
        actual_phases = _valid_phase_count(st.get("phases_actual"), 0)
    if not actual_phases:
        phase_powers = [
            abs(_cfg_float(st.get("phase_power_l1_w"), 0.0)),
            abs(_cfg_float(st.get("phase_power_l2_w"), 0.0)),
            abs(_cfg_float(st.get("phase_power_l3_w"), 0.0)),
        ]
        active_phase_count = sum(1 for value in phase_powers if value > 100.0)
        actual_phases = active_phase_count if active_phase_count in (1, 2, 3) else 0

    charger = box.get("charger")
    charger_class = charger.__class__.__name__ if charger is not None else str(box.get("_charger_class_name", "") or "")
    phase_text = "%dp" % actual_phases if actual_phases > 0 else "Phasen unklar"
    reason = (
        "Wallbox bietet seit mindestens 45 s stabil %.1f A/%dp an, "
        "die Abnahme unter Stromangebot beträgt aber nur %.0f W "
        "(%.0f%% von ca. %.0f W, %s). E3DC-Control kann nur freigeben; "
        "Onboardlader, Fahrzeug-SoC/Temperatur, Kabel/Phasen, Wallbox-Profil und App-Limit prüfen."
    ) % (
        target_amp,
        target_phases,
        real_power_w,
        accepted_ratio * 100.0,
        expected_power_w,
        phase_text,
    )
    return {
        "state": "Abnahme unter Stromangebot",
        "state_level": "warning",
        "state_reason": reason,
        "control_status": "vehicle_under_acceptance",
        "control_label": "Fahrzeug nimmt weniger",
        "control_detail": reason,
        "control_level": "warning",
        "vehicle_under_acceptance_warning": True,
        "vehicle_under_acceptance_reason": reason,
        "vehicle_under_acceptance_offered_amp": round(target_amp, 1),
        "vehicle_under_acceptance_target_phases": int(target_phases),
        "vehicle_under_acceptance_actual_power_w": round(real_power_w, 1),
        "vehicle_under_acceptance_expected_power_w": round(expected_power_w, 1),
        "vehicle_under_acceptance_accepted_ratio": round(accepted_ratio, 3),
        "vehicle_under_acceptance_actual_phases": int(actual_phases or 0),
        "vehicle_under_acceptance_charger_class": charger_class,
    }


WB_DECISION_LATEST_FILE = os.path.join(RAMDISK_DIR, "wallbox_decision_latest.json")
WB_DECISION_HISTORY_PREFIX = "wallbox_decision_history_"
WB_ABORT_RETRY_LIMIT = 1
_wallbox_diagnostics = WallboxDiagnostics(
    log_dir=LOG_DIR,
    latest_path=WB_DECISION_LATEST_FILE,
    history_prefix=WB_DECISION_HISTORY_PREFIX,
    ems_path=EMS_DECISION_FILE,
    logger=logger,
)
_wallbox_status_service = StatusService(logger)
_storage_intent_publisher = StorageIntentPublisher(WB_STORAGE_INTENT_FILE, logger=logger)
_wallbox_command_executor = CommandExecutor(logger)
_charger_controller = ChargerController()


def wallbox_loop_sleep_s(
    config,
    *,
    made_changes=False,
    statuses=None,
    wb_details=None,
    scheduled_slot_active=False,
    price_boost_active=False,
    predump_wallbox_active=False,
    budget_stale=False,
    budget_timeout=False,
    storage_state="",
):
    """Return the next manager-loop sleep time without changing control rules."""

    statuses = statuses or []
    wb_details = wb_details or []
    active_storage_states = {
        "parallel_wb_auto",
        "parallel_curve_charge",
        "parallel_curve_charge_cap",
        "parallel_grid_relief_auto",
        "pre_discharge",
        "pre_discharge_wait",
        "pre_discharge_consumer_auto",
        "price_boost_grid",
        "storm_guard_grid",
    }
    any_connected = any(_wb_status_connected(item.get("status")) for item in statuses if isinstance(item, dict))
    any_charging = any(_wb_status_real_charging(item.get("status")) for item in statuses if isinstance(item, dict))
    any_detail_edge = any(
        bool(detail.get("plug") or detail.get("charging"))
        for detail in wb_details
        if isinstance(detail, dict)
    )
    active_edge = bool(
        made_changes
        or any_connected
        or any_charging
        or any_detail_edge
        or scheduled_slot_active
        or price_boost_active
        or predump_wallbox_active
        or budget_stale
        or budget_timeout
        or str(storage_state or "") in active_storage_states
    )
    if active_edge:
        return 2.0
    idle_s = _cfg_float((config or {}).get("wb_idle_poll_s"), 6.0)
    return max(2.0, min(10.0, idle_s))


def _cfg_float(value, default=0.0):
    try:
        s = str(value).strip() if value is not None else ""
        return float(s) if s else float(default)
    except (TypeError, ValueError):
        return float(default)


def _cfg_int(value, default=0):
    try:
        s = str(value).strip() if value is not None else ""
        return int(float(s)) if s else int(default)
    except (TypeError, ValueError):
        return int(default)

def _first_cfg_float(*values, default=0.0):
    for value in values:
        try:
            if value is None:
                continue
            text = str(value).strip()
            if not text:
                continue
            result = float(text)
            if math.isfinite(result):
                return result
        except (TypeError, ValueError):
            continue
    return float(default)

def _first_present(*values):
    for value in values:
        if value is None:
            continue
        if isinstance(value, str) and not value.strip():
            continue
        return value
    return None

def _ts_seconds(value, default=0.0):
    try:
        if value is None:
            return float(default)
        ts = float(value)
        if not math.isfinite(ts) or ts <= 0:
            return float(default)
        if ts > 10_000_000_000:
            ts /= 1000.0
        return ts
    except (TypeError, ValueError):
        return float(default)

def _amp_limit(value, fallback=16):
    amp = int(round(_cfg_float(value, fallback)))
    return max(6, min(32, amp))

BATTERY_DEPARTURE_DEFAULT_TIME = "06:30"
BATTERY_DEPARTURE_DEFAULT_WINDOW_H = 3.0


def _parse_hhmm(value, default=BATTERY_DEPARTURE_DEFAULT_TIME):
    text = str(value if value not in (None, "") else default).strip()
    if len(text) >= 5 and ":" in text:
        parts = text.split(":", 1)
        try:
            hour = int(parts[0])
            minute = int(parts[1][:2])
            if 0 <= hour <= 23 and 0 <= minute <= 59:
                return hour, minute, f"{hour:02d}:{minute:02d}"
        except (TypeError, ValueError):
            pass
    return 6, 30, BATTERY_DEPARTURE_DEFAULT_TIME


def _battery_departure_window_s(config, charger_id=None):
    keys = []
    if charger_id is not None:
        keys.append(f"wb{int(charger_id)}_battery_departure_window_h")
    keys.append("wb_battery_departure_window_h")
    raw = None
    for key in keys:
        if key in config and str(config.get(key, "")).strip() != "":
            raw = config.get(key)
            break
    hours = _cfg_float(raw, BATTERY_DEPARTURE_DEFAULT_WINDOW_H)
    return max(1.0, min(36.0, hours)) * 3600.0


def _battery_departure_state(config, charger_id, public_mode, now_ts=None):
    """Return the active/blocked state for the battery-only departure mode."""
    if normalize_wb_mode(public_mode) != MODE_BATTERY_DEPARTURE:
        return {"configured": False, "active": False, "blocked": False}
    now_ts = time.time() if now_ts is None else float(now_ts)
    key = f"wb{int(charger_id)}_battery_departure_time"
    hour, minute, label = _parse_hhmm(
        config.get(key, config.get("wb_battery_departure_time", BATTERY_DEPARTURE_DEFAULT_TIME))
    )
    now_local = time.localtime(now_ts)
    deadline_tuple = (
        now_local.tm_year,
        now_local.tm_mon,
        now_local.tm_mday,
        hour,
        minute,
        0,
        now_local.tm_wday,
        now_local.tm_yday,
        now_local.tm_isdst,
    )
    deadline_ts = time.mktime(deadline_tuple)
    if now_ts > deadline_ts and now_local.tm_hour >= 12:
        deadline_ts += 86400.0
    remaining_s = deadline_ts - now_ts
    window_s = _battery_departure_window_s(config, charger_id)
    start_ts = deadline_ts - window_s
    active = 0.0 <= remaining_s <= window_s
    expired = remaining_s < 0.0
    blocked = not active
    reason = "active" if active else ("departure_reached" if expired else "outside_window")
    return {
        "configured": True,
        "active": active,
        "blocked": blocked,
        "expired": expired,
        "reason": reason,
        "deadline_ts": deadline_ts,
        "start_ts": start_ts,
        "departure_time": label,
        "start_time": time.strftime("%H:%M", time.localtime(start_ts)),
        "remaining_s": remaining_s,
        "window_s": window_s,
        "window_h": round(window_s / 3600.0, 2),
    }


def _battery_departure_target_reached(config, charger_id, status):
    """Return whether Akku-bis-Abfahrt should be considered finished by SoC."""
    if not _wb_status_connected(status):
        return False, -1.0, 100.0
    if not _car_soc_rule_confirmed(status):
        return False, -1.0, 100.0
    try:
        car_soc = float((status or {}).get("car_soc"))
    except (TypeError, ValueError):
        return False, -1.0, 100.0
    if car_soc < 0.0:
        return False, car_soc, 100.0

    target_soc = 100.0
    cfg = config or {}
    key = f"wb{int(charger_id or 1)}_target_soc"
    raw_target = cfg.get(key)
    if raw_target is not None and str(raw_target).strip() != "":
        target_soc = _cfg_float(raw_target, 100.0)
    target_soc = max(5.0, min(100.0, target_soc))
    threshold = 99.5 if target_soc >= 99.5 else max(0.0, target_soc - 0.5)
    return car_soc >= threshold, car_soc, target_soc


def _wallbox_target_soc_not_reached(config, charger_id, status):
    """Return true when a confirmed vehicle SoC proves that a charge-end latch is stale."""
    reached, car_soc, target_soc = _battery_departure_target_reached(config, charger_id, status)
    if car_soc < 0.0:
        return False, car_soc, target_soc
    return bool(not reached), car_soc, target_soc


def _wallbox_target_kwh_reached(config, charger_id, status):
    """Return whether the current wallbox session reached its kWh target."""
    cfg = config or {}
    cid = int(charger_id or 1)
    target_unit = str(cfg.get(f"wb{cid}_target_unit", cfg.get("car_target_unit", "soc"))).strip().lower()
    if target_unit != "kwh" or not _wb_status_connected(status):
        return False, -1.0, 0.0
    target_kwh = _cfg_float(cfg.get(f"wb{cid}_target_kwh", cfg.get("car_target_kwh", 0.0)), 0.0)
    if target_kwh <= 0.05:
        return False, -1.0, target_kwh
    session_kwh = _first_cfg_float(
        (status or {}).get("session_kwh"),
        (status or {}).get("kwh"),
        (status or {}).get("session_energy_kwh"),
        default=-1.0,
    )
    if session_kwh < 0.0:
        return False, session_kwh, target_kwh
    return session_kwh + 0.02 >= target_kwh, session_kwh, target_kwh


def _wallbox_target_stop_owner_contract(openwb_primary_controller, reason):
    """Trennt Manager-Zielstopps vom extern geführten openWB-Primary-Pfad."""

    external_owner = bool(openwb_primary_controller)
    return {
        "contract": "wallbox_target_stop_owner_v1",
        "reason": str(reason or "target_reached"),
        "control_owner": "openwb_primary" if external_owner else "wallbox_manager",
        "manager_stop_authorized": not external_owner,
        "action": "diagnostic_only" if external_owner else "manager_stop",
    }


def _mode_priority(public_mode):
    mode = normalize_wb_mode(public_mode)
    if mode == MODE_OFF:
        return 0
    if mode == MODE_CURVE:
        return 20
    if mode == MODE_BASE:
        return 30
    if mode in (MODE_TARGET, MODE_BATTERY_DEPARTURE):
        return 40
    if mode == MODE_PRICE:
        return 50
    return 20


def _select_effective_public_wb_mode(wb_charge_mode, charger_ids, blocked_ids=None):
    blocked_ids = set(blocked_ids or [])
    best_mode = MODE_OFF
    best_rank = -1
    for cid in charger_ids or []:
        mode = MODE_OFF if int(cid) in blocked_ids else normalize_wb_mode(wb_charge_mode.get(int(cid), MODE_OFF))
        rank = _mode_priority(mode)
        if rank > best_rank:
            best_rank = rank
            best_mode = mode
    return best_mode

_write_json_atomic = _wallbox_diagnostics.write_json_atomic
_cleanup_wallbox_decision_history = _wallbox_diagnostics.cleanup_history
write_wallbox_decision_history = _wallbox_diagnostics.write_history
write_wallbox_decision_snapshot = _wallbox_diagnostics.write_snapshot

def _plan_wallbox_decision_payload(payload):
    if not isinstance(payload, dict):
        return {}, {}
    controller_result = _charger_controller.plan_payload(payload, now_ts=time.time())
    driver_command = controller_result.command
    payload["driver_command"] = driver_command
    controller_diagnostic = {
        "enabled": True,
        "authoritative": True,
        "valid": bool(controller_result.valid),
        "reason": controller_result.reason,
        "error": controller_result.error,
        "command": driver_command,
    }
    return driver_command, controller_diagnostic


def _remember_wallbox_decision_payload(c_data, payload):
    if not isinstance(c_data, dict) or not isinstance(payload, dict):
        return {}
    driver_command, controller_diagnostic = _plan_wallbox_decision_payload(payload)
    c_data["_decision_payload"] = payload
    c_data["_driver_command"] = driver_command
    c_data["_charger_controller"] = controller_diagnostic
    return driver_command

def _wallbox_decision_payload_or_default(
    c_data,
    status,
    *,
    public_mode=0,
    control_mode=None,
    cap_amp=0,
    allowed_w=0,
    detected_phases=1,
    max_amp=0,
    mode_label_text="",
    storage_state="",
    budget_timeout=False,
):
    if not isinstance(c_data, dict):
        c_data = {}
    try:
        c_id = int(c_data.get("id", 0) or 0)
    except Exception:
        c_id = 0
    existing = c_data.get("_decision_payload")
    if isinstance(existing, dict) and int(existing.get("wb_id", c_id) or 0) == c_id:
        command = c_data.get("_driver_command")
        if not isinstance(command, dict):
            command = _remember_wallbox_decision_payload(c_data, existing)
            existing["driver_command"] = command
        return existing, command

    public = normalize_wb_mode(public_mode)
    control = controller_mode(public) if control_mode is None else int(control_mode or 0)
    connected = _wb_status_connected(status)
    real_state = _wb_status_real_charging(status)
    real_power_w = _wb_status_real_power(status) if real_state else 0.0
    try:
        status_amp = float(
            (status or {}).get("offered_current_raw")
            or (status or {}).get("evse_current")
            or (status or {}).get("amp", 0)
            or 0.0
        )
    except Exception:
        status_amp = 0.0
    charger = c_data.get("charger")
    driver_class_name = charger.__class__.__name__ if charger is not None else ""
    openwb_pro = bool(driver_class_name == "OpenWBProCharger")
    openwb_like = bool(driver_class_name == "OpenWBCharger")
    e3dc_native_toggle = bool(
        charger is not None
        and hasattr(charger, "set_amp_sonnenmodus")
        and not hasattr(charger, "set_pv_mode")
    )
    target_amp = float(cap_amp or 0.0)
    start_action = "NOOP"
    start_reason = "mode_off" if public == 0 else ("no_vehicle_connected" if not connected else "observe_only")
    if public > 0 and connected and target_amp > 0:
        start_action = "START" if status_amp <= 0 and float(c_data.get("current_set_amp", 0) or 0) <= 0 else "SET_CURRENT"
        start_reason = "target_current_available"
    payload = wallbox_decision.build_wallbox_decision_payload(
        wb_id=c_id,
        public_mode=public,
        control_mode=control,
        current_decision={
            "target_amp": target_amp,
            "raw_amp": target_amp,
            "physically_chargeable": bool(target_amp > 0 and connected),
            "house_fuse_limited": False,
            "limiting_reason": start_reason,
        },
        start_stop_decision={
            "action": start_action,
            "target_amp": target_amp if start_action in ("START", "SET_CURRENT") else 0,
            "hold_amp": target_amp if start_action in ("START", "SET_CURRENT") else 0,
            "reason": start_reason,
        },
        phase_recommendation={
            "action": "KEEP_PHASES",
            "target_phases": 0,
            "reason": "stable",
            "wait_s": 0,
            "remaining_s": 0,
        },
        allowed_w=allowed_w,
        detected_phases=detected_phases,
        current_amp=status_amp,
        current_set_amp=float(c_data.get("current_set_amp", 0) or 0),
        cap_amp=float(cap_amp or 0),
        max_amp=int(max_amp or 0),
        charger_connected=connected,
        hw_charging=real_state,
        hw_power_w=real_power_w,
        mode_label=mode_label_text or mode_label(public),
        storage_state=storage_state,
        driver_class_name=driver_class_name,
        openwb_like_charger=openwb_like,
        openwb_pro=openwb_pro,
        e3dc_native_toggle=e3dc_native_toggle,
        observe_only=bool(public == 0 or not connected),
        budget_timeout=budget_timeout,
    )
    command, controller_diagnostic = _plan_wallbox_decision_payload(payload)
    c_data["_charger_controller"] = controller_diagnostic
    return payload, command


def _wallbox_e3dc_native_production_contract(
    c_data,
    status=None,
    config=None,
    *,
    charger_class_name="",
):
    box = c_data if isinstance(c_data, dict) else {}
    charger = box.get("charger")
    class_name = str(charger_class_name or "")
    if not class_name:
        class_name = charger.__class__.__name__ if charger is not None else str(box.get("_charger_class_name", "") or "")
    driver_variant = str((status or {}).get("driver_variant") or box.get("driver_variant") or "")
    return wallbox_decision.e3dc_native_production_contract(
        class_name,
        status,
        config,
        driver_variant=driver_variant,
        has_sonnenmodus_surface=bool(charger is not None and hasattr(charger, "set_amp_sonnenmodus")),
    )


def _apply_e3dc_native_production_contract_to_status(status, contract):
    if status is None or not isinstance(contract, dict):
        return status
    status["e3dc_native_contract"] = contract
    status["e3dc_native_runtime_path"] = str(contract.get("runtime_path", "not_e3dc") or "not_e3dc")
    status["e3dc_native_legacy_cpp_runtime_allowed"] = bool(contract.get("legacy_cpp_runtime_allowed", False))
    status["e3dc_native_fallback_role"] = str(contract.get("fallback_role", "") or "")
    status["e3dc_native_session_guard_required"] = bool(contract.get("session_guard_required", False))
    status["e3dc_native_charge_verification_required"] = bool(contract.get("charge_verification_required", False))
    return status


def _storage_floor_reachable(plan, battery_soc, floor_soc, hysteresis_pct=0.0):
    """Return whether the house battery floor is still reachable.

    ``can_reach_target`` may refer to the higher day target. Grundladung stabil
    only needs the wbminSoC floor: it should hold 6A until that floor is no
    longer reachable.
    """
    try:
        floor = float(floor_soc)
    except (TypeError, ValueError):
        return True
    if floor <= 0:
        return True

    try:
        current_soc = float(battery_soc)
    except (TypeError, ValueError):
        current_soc = None
    try:
        hyst = max(0.0, float(hysteresis_pct or 0.0))
    except (TypeError, ValueError):
        hyst = 0.0

    if current_soc is not None and current_soc >= floor - hyst:
        return True

    plan = plan if isinstance(plan, dict) else {}
    if not plan:
        return True
    if plan.get("can_reach_target") is True:
        return True

    meta = plan.get("target_curve_meta") if isinstance(plan.get("target_curve_meta"), dict) else {}
    for source in (plan, meta):
        raw = source.get("max_reachable_soc")
        if raw is None:
            continue
        try:
            return float(raw) >= floor - hyst
        except (TypeError, ValueError):
            continue

    if plan.get("can_reach_target") is False:
        return False
    return True


def _wbminsoc_discharge_taper_factor(soc_diff_pct, taper_above_pct):
    try:
        diff = max(0.0, float(soc_diff_pct or 0.0))
    except (TypeError, ValueError):
        return 1.0
    try:
        band = max(0.0, float(taper_above_pct or 0.0))
    except (TypeError, ValueError):
        band = 0.0
    if band <= 0.0 or diff >= band:
        return 1.0
    if diff <= 0.0:
        return 0.0
    linear = max(0.0, min(1.0, diff / band))
    return linear * linear


def _pv_only_allowed_power_w(
    *,
    wb_actual_power_w,
    grid_export_room_w,
    grid_import_for_budget_w,
    battery_discharge_w,
):
    """Ermittelt die batterieneutrale Leistung für eine PV-geführte Wallbox.

    Der Netzpunkt allein trennt PV- und Batterieunterstützung nicht: Eine
    laufende Wallbox mit gleich hoher Batterieentladung sieht ebenfalls wie
    ein ausgeglichener Netzpunkt aus. Deshalb wird die gemessene
    Batterieentladung abgezogen. Echte Einspeisung bleibt als zusätzlicher
    PV-Puffer nutzbar.
    """

    def _non_negative(value):
        try:
            return max(0.0, float(value or 0.0))
        except (TypeError, ValueError):
            return 0.0

    return max(
        0.0,
        _non_negative(wb_actual_power_w)
        + _non_negative(grid_export_room_w)
        - _non_negative(grid_import_for_budget_w)
        - _non_negative(battery_discharge_w),
    )


def _wbminsoc_floor_pv_start_ready(
    *,
    control_mode,
    wbminsoc_gate_open,
    cap_amp,
    real_surplus_w,
    min_power_w,
    startable_connected,
    manual_pause,
    grid_allowed,
):
    try:
        mode = int(control_mode or 0)
    except (TypeError, ValueError):
        mode = 0
    try:
        cap = int(round(float(cap_amp or 0)))
    except (TypeError, ValueError):
        cap = 0
    try:
        surplus = float(real_surplus_w or 0.0)
    except (TypeError, ValueError):
        surplus = 0.0
    try:
        minimum = float(min_power_w or 0.0)
    except (TypeError, ValueError):
        minimum = 0.0

    return bool(
        mode in (9, 10, 11)
        and not bool(wbminsoc_gate_open)
        and bool(startable_connected)
        and not bool(manual_pause)
        and not bool(grid_allowed)
        and cap > 0
        and surplus >= max(750.0, minimum - 250.0)
    )


def _curve_floor_pv_only_start_release_ready(
    *,
    curve_floor_guard_active,
    charger_connected,
    real_surplus_w,
    battery_discharge_w,
    min_power_w,
    allocated_w,
    manual_pause,
    locked,
    grid_allowed,
    price_active,
    price_boost_active,
    predump_active,
    budget_timeout,
):
    if not bool(curve_floor_guard_active):
        return False
    if not bool(charger_connected) or bool(manual_pause) or bool(locked):
        return False
    if bool(grid_allowed) or bool(price_active) or bool(price_boost_active) or bool(predump_active) or bool(budget_timeout):
        return False
    try:
        surplus = float(real_surplus_w or 0.0)
    except (TypeError, ValueError):
        surplus = 0.0
    try:
        discharge = float(battery_discharge_w or 0.0)
    except (TypeError, ValueError):
        discharge = 0.0
    try:
        minimum = float(min_power_w or 0.0)
    except (TypeError, ValueError):
        minimum = 0.0
    try:
        allocated = float(allocated_w or 0.0)
    except (TypeError, ValueError):
        allocated = 0.0

    net_surplus = surplus - max(0.0, discharge)
    threshold = max(750.0, minimum - 250.0)
    return bool(net_surplus >= threshold and allocated >= threshold)



def _wbminsoc_floor_battery_hard_stop_due(
    *,
    floor_battery_support_active,
    floor_pv_buffer_ready,
    floor_battery_age_s,
    floor_battery_stop_delay_s,
    floor_effective_surplus_w,
    floor_min_hold_w,
    floor_gross_surplus_w=0.0,
):
    if not bool(floor_battery_support_active):
        return False
    if bool(floor_pv_buffer_ready):
        return False
    try:
        age_s = float(floor_battery_age_s or 0.0)
    except (TypeError, ValueError):
        age_s = 0.0
    try:
        delay_s = max(0.0, float(floor_battery_stop_delay_s or 0.0))
    except (TypeError, ValueError):
        delay_s = 0.0
    try:
        surplus_w = float(floor_effective_surplus_w or 0.0)
    except (TypeError, ValueError):
        surplus_w = 0.0
    try:
        gross_surplus_w = float(floor_gross_surplus_w or 0.0)
    except (TypeError, ValueError):
        gross_surplus_w = 0.0
    try:
        min_hold_w = float(floor_min_hold_w or 0.0)
    except (TypeError, ValueError):
        min_hold_w = 0.0
    hold_threshold_w = max(750.0, min_hold_w - 250.0)
    return bool(
        age_s >= delay_s
        and surplus_w < hold_threshold_w
        and gross_surplus_w < hold_threshold_w
    )


def _e3dc_native_floor_battery_stop_now(
    *,
    e3dc_native_toggle,
    charger_connected,
    verified_active_charge,
    cap_amp,
    target_budget_w,
    floor_battery_support_active,
    floor_effective_surplus_w,
    floor_min_hold_w,
    priority_forced_stop=False,
    local_price_optimizing_active=False,
    local_grid_allowed=False,
    price_boost_wallbox_active=False,
    budget_timeout=False,
    predump_wallbox_active=False,
):
    """Return true for a verified native charge that must not use the battery floor."""
    try:
        cap = int(round(float(cap_amp or 0)))
    except (TypeError, ValueError):
        cap = 0
    try:
        budget_w = float(target_budget_w or 0.0)
    except (TypeError, ValueError):
        budget_w = 0.0
    try:
        surplus_w = float(floor_effective_surplus_w or 0.0)
    except (TypeError, ValueError):
        surplus_w = 0.0
    try:
        min_hold_w = float(floor_min_hold_w or 0.0)
    except (TypeError, ValueError):
        min_hold_w = 0.0
    hold_threshold_w = max(750.0, min_hold_w - 250.0)
    return bool(
        e3dc_native_toggle
        and charger_connected
        and verified_active_charge
        and cap <= 0
        and budget_w <= 0.0
        and floor_battery_support_active
        and surplus_w < hold_threshold_w
        and not priority_forced_stop
        and not local_price_optimizing_active
        and not local_grid_allowed
        and not price_boost_wallbox_active
        and not budget_timeout
        and not predump_wallbox_active
    )


def _e3dc_native_storage_floor_direct_current(
    *,
    e3dc_native_toggle,
    control_mode,
    wbminsoc_gate_open,
    discharge_pull_active,
    discharge_taper_active=False,
    floor_pv_only_guard=False,
    storage_charge_priority_active=False,
    priority_forced_stop=False,
    budget_timeout=False,
    predump_wallbox_active=False,
    local_price_optimizing_active=False,
    local_grid_allowed=False,
    price_boost_wallbox_active=False,
):
    """Wählt exakten Sollstrom für native PV+Akku-Ladung oberhalb des Floors."""

    try:
        mode = int(control_mode or 0)
    except (TypeError, ValueError):
        mode = 0
    return bool(
        e3dc_native_toggle
        and mode in (10, 11)
        and wbminsoc_gate_open
        and discharge_pull_active
        and not discharge_taper_active
        and not floor_pv_only_guard
        and not storage_charge_priority_active
        and not priority_forced_stop
        and not budget_timeout
        and not predump_wallbox_active
        and not local_price_optimizing_active
        and not local_grid_allowed
        and not price_boost_wallbox_active
    )


def _phase_forecast_holds(plan):
    """Return whether today's forecast is good enough to keep WB phases calm."""
    plan = plan if isinstance(plan, dict) else {}
    if not plan:
        return False
    if plan.get("can_reach_target") is True:
        return True

    meta = plan.get("target_curve_meta") if isinstance(plan.get("target_curve_meta"), dict) else {}

    def _first_float(*values):
        for value in values:
            try:
                if value is None:
                    continue
                return float(value)
            except (TypeError, ValueError):
                continue
        return None

    target_soc = _first_float(
        plan.get("effective_target_soc"),
        plan.get("target_soc"),
        meta.get("curve_end_soc"),
    )
    max_soc = _first_float(
        plan.get("max_soc_pct"),
        plan.get("max_reachable_soc"),
        meta.get("max_soc_pct"),
    )
    if target_soc is not None and max_soc is not None:
        return max_soc >= target_soc - 0.5
    return False


def _storage_budget_forecast_holds(budget):
    """Return whether the fresh storage budget carries a forecast hold contract."""

    budget = budget if isinstance(budget, dict) else {}
    state = str(budget.get("storage_state", budget.get("state", "")) or "")
    if state != "parallel_curve_auto_hold":
        return False
    return bool(
        _truthy_config(budget.get("forecast_curve_landing_hold_active"))
        or _truthy_config(budget.get("sliding_horizon_active"))
    )


def _curve_forecast_wallbox_guard(plan, budget, config, now_ts=None, storage_forecast_hold_active=None, storage_authorized_w=0.0):
    """Return the forecast gate for PV-curve wallbox battery assist."""

    plan = plan if isinstance(plan, dict) else {}
    budget = budget if isinstance(budget, dict) else {}
    config = config if isinstance(config, dict) else {}
    meta = plan.get("target_curve_meta") if isinstance(plan.get("target_curve_meta"), dict) else {}
    now = time.time() if now_ts is None else float(now_ts or 0.0)

    stop_wh = max(0.0, _cfg_float(config.get("wb_curve_forecast_stop_shortfall_wh"), 500.0))
    release_wh = max(
        0.0,
        min(stop_wh, _cfg_float(config.get("wb_curve_forecast_release_shortfall_wh"), 100.0)),
    )
    stop_gap_pct = max(0.0, _cfg_float(config.get("wb_curve_forecast_stop_gap_pct"), 0.5))
    release_gap_pct = max(
        0.0,
        min(stop_gap_pct, _cfg_float(config.get("wb_curve_forecast_release_gap_pct"), 0.2)),
    )
    release_hold_s = max(0.0, _cfg_float(config.get("wb_curve_forecast_release_hold_s"), 90.0))

    budget_forecast_hold_active = (
        _storage_budget_forecast_holds(budget)
        if storage_forecast_hold_active is None
        else bool(storage_forecast_hold_active)
    )
    can_reach_target = plan.get("can_reach_target", True)
    evening_shortfall_wh = max(
        0.0,
        _first_cfg_float(
            budget.get("evening_shortfall_wh"),
            plan.get("evening_shortfall_wh"),
            meta.get("evening_shortfall_wh"),
            default=0.0,
        ),
    )
    target_gap_pct = max(
        0.0,
        _first_cfg_float(
            budget.get("shortfall_target_gap_pct"),
            budget.get("forecast_floor_target_gap_pct"),
            plan.get("shortfall_target_gap_pct"),
            meta.get("shortfall_target_gap_pct"),
            default=0.0,
        ),
    )
    latest_charge_start_s = _ts_seconds(
        _first_present(
            budget.get("latest_charge_start_ts"),
            plan.get("latest_charge_start_ts"),
            meta.get("latest_charge_start_ts"),
        )
    )
    latest_charge_due = bool(latest_charge_start_s > 0.0 and now >= latest_charge_start_s)

    try:
        raw_val = float(storage_authorized_w or 0.0)
        storage_auth_w = 0.0 if math.isnan(raw_val) else max(0.0, raw_val)
    except (TypeError, ValueError):
        storage_auth_w = 0.0
    storage_budget_authorized = bool(storage_auth_w >= 1380.0)

    block_unreachable = bool(can_reach_target is False and not budget_forecast_hold_active)
    block_shortfall = bool(stop_wh > 0.0 and evening_shortfall_wh >= stop_wh)
    block_late_gap = bool(
        latest_charge_due
        and stop_gap_pct > 0.0
        and target_gap_pct >= stop_gap_pct
        and not budget_forecast_hold_active
    )
    forecast_block_requested = bool(block_unreachable or block_shortfall or block_late_gap)
    forecast_release_ready = bool(
        (budget_forecast_hold_active or can_reach_target is not False)
        and evening_shortfall_wh <= release_wh
        and (budget_forecast_hold_active or target_gap_pct <= release_gap_pct)
    )

    forecast_reason = "ok"
    if block_unreachable:
        forecast_reason = "target_unreachable"
    elif block_shortfall:
        forecast_reason = "evening_shortfall"
    elif block_late_gap:
        forecast_reason = "latest_charge_gap"
    elif not forecast_release_ready:
        forecast_reason = "recovery_wait"

    if storage_budget_authorized:
        block_requested = False
        release_ready = True
        assist_allowed = False
        reason = "storage_budget_authorized"
    else:
        block_requested = forecast_block_requested
        release_ready = forecast_release_ready
        assist_allowed = bool(release_ready and not block_requested)
        reason = forecast_reason

    return {
        "block_requested": block_requested,
        "release_ready": release_ready,
        "assist_allowed": assist_allowed,
        "storage_budget_authorized": storage_budget_authorized,
        "reason": reason,
        "forecast_reason": forecast_reason,
        "forecast_block_requested": forecast_block_requested,
        "forecast_release_ready": forecast_release_ready,
        "can_reach_target": can_reach_target,
        "storage_forecast_hold_active": budget_forecast_hold_active,
        "evening_shortfall_wh": round(evening_shortfall_wh, 0),
        "target_gap_pct": round(target_gap_pct, 3),
        "latest_charge_start_ts": latest_charge_start_s,
        "latest_charge_due": latest_charge_due,
        "stop_shortfall_wh": round(stop_wh, 0),
        "release_shortfall_wh": round(release_wh, 0),
        "stop_gap_pct": round(stop_gap_pct, 3),
        "release_gap_pct": round(release_gap_pct, 3),
        "release_hold_s": release_hold_s,
    }

def _normalize_current_step_amp(value, default=1.0):
    try:
        step = float(value or default)
    except (TypeError, ValueError):
        step = float(default)
    if step <= 0.11:
        return 0.1
    if step <= 0.51:
        return 0.5
    return 1.0


def _current_step_amp_for_charger(charger, default=1.0):
    val = getattr(charger, "current_step_amp", None)
    if val is None and hasattr(charger, "config") and isinstance(charger.config, dict):
        val = charger.config.get("wb_current_step_amp")
    if val is None and hasattr(charger, "state") and isinstance(charger.state, dict):
        val = charger.state.get("current_step_amp")
    return _normalize_current_step_amp(val if val is not None else default, default=default)



def _budget_current_step_amp_for_chargers(
    chargers,
    wb_charge_mode=None,
    wb_locked=None,
    wb_manual_pause=None,
    status_by_id=None,
):
    """Ermittelt die minimale Regelschrittweite nur aus sicher kommandierbaren Boxen.

    1. Sicher kommandierbar: driver_status_valid is True, driver_status_stale is not True,
       connected is True, mode != MODE_OFF, neither locked nor paused.
    2. Sicher nicht beteiligt: frisch und valide als connected=False gemeldet.
    3. Unklar / stale / ungültig: konservativer 1,0-A-Kandidat (fail-closed).
    """
    candidates = []
    for c_data in chargers or []:
        if not isinstance(c_data, dict):
            candidates.append(1.0)
            continue
        cid = int(c_data.get("id", 0) or 0)
        if wb_locked and bool(wb_locked.get(cid, False)):
            continue
        if wb_manual_pause and bool(wb_manual_pause.get(cid, False)):
            continue
        if wb_charge_mode and normalize_wb_mode(wb_charge_mode.get(cid, MODE_OFF)) == MODE_OFF:
            continue
        charger = c_data.get("charger")
        if charger is None:
            continue
        st = None
        if isinstance(status_by_id, dict) and isinstance(status_by_id.get(cid), dict):
            st = status_by_id.get(cid)
        elif isinstance(c_data.get("status"), dict):
            st = c_data.get("status")
        elif hasattr(charger, "state") and isinstance(getattr(charger, "state", None), dict):
            st = charger.state
        elif hasattr(charger, "get_status") and callable(getattr(charger, "get_status", None)):
            try:
                st = charger.get_status()
            except Exception:
                st = None

        if isinstance(st, dict):
            status_valid = st.get("driver_status_valid") is True
            status_stale = st.get("driver_status_stale") is True
            if st.get("connected") is not None:
                connected = bool(st.get("connected"))
            else:
                connected = bool(
                    st.get("plug_state") is True
                    or st.get("car_connected_rscp") is True
                    or (
                        bool(st.get("car"))
                        and str(st.get("car")).lower()
                        not in ("0", "false", "none", "off", "unplugged", "disconnected")
                    )
                )

            if status_valid and not status_stale:
                if not connected:
                    # Sicher nicht beteiligt: frisch und valide ausgesteckt
                    continue
                # Sicher kommandierbar: frisch, valide und verbunden
                step = _current_step_amp_for_charger(charger, default=1.0)
                candidates.append(step)
                continue

        # Status unklar, ungültig oder stale: konservativ 1,0 A Fallback
        candidates.append(1.0)

    if len(candidates) == 1:
        return candidates[0]
    if candidates and all(c <= 0.11 for c in candidates):
        return 0.1
    return 1.0


def _round_amp_down_to_step(value, step):
    step = _normalize_current_step_amp(step, default=1.0)
    rounded = math.floor(max(0.0, float(value or 0.0)) / step) * step
    return float(int(round(rounded))) if step >= 0.99 else round(rounded, 1)


def _round_amp_up_to_step(value, step):
    step = _normalize_current_step_amp(step, default=1.0)
    rounded = math.ceil(max(0.0, float(value or 0.0)) / step) * step
    return float(int(round(rounded))) if step >= 0.99 else round(rounded, 1)


def _amp_text(value):
    try:
        amp = float(value or 0.0)
    except (TypeError, ValueError):
        amp = 0.0
    if abs(amp - round(amp)) < 0.01:
        return str(int(round(amp)))
    return f"{amp:.1f}"


def _openwb_pro_effective_w_per_amp(status, phases=None, current_amp=0.0):
    def _local_float(value, default=0.0):
        try:
            return float(value if value is not None else default)
        except (TypeError, ValueError):
            return float(default)

    st = status if isinstance(status, dict) else {}
    phase_count = max(
        1,
        int(
            phases
            or st.get("phases_in_use")
            or st.get("phase_effective_phases")
            or st.get("phases_actual")
            or st.get("phases_target")
            or 1
        ),
    )
    nominal_w_per_amp = 230.0 * float(phase_count)
    real_power_w = max(
        0.0,
        _local_float(st.get("phase_power_sum_w", 0.0), 0.0),
        _local_float(st.get("real_power_w", 0.0), 0.0),
    )
    offered_amp = max(
        _local_float(st.get("offered_current_raw", 0.0), 0.0),
        _local_float(st.get("evse_current", 0.0), 0.0),
        _local_float(st.get("amp", 0.0), 0.0),
        _local_float(current_amp, 0.0),
    )
    if real_power_w <= 500.0 or offered_amp < 5.5:
        return 0.0
    measured_w_per_amp = real_power_w / offered_amp
    if measured_w_per_amp <= 0.0:
        return 0.0
    return max(nominal_w_per_amp * 0.55, min(nominal_w_per_amp * 1.10, measured_w_per_amp))


def _openwb_pro_curve_direct_amp(target_w, phases, charger_max_amp, *, assist_allowed=False, assist_max_gap_w=0.0, current_step_amp=1.0, watts_per_amp=0.0):
    phase_count = max(1, int(phases or 1))
    max_amp = max(6, int(charger_max_amp or 16))
    step = _normalize_current_step_amp(current_step_amp, default=1.0)
    target = max(0.0, float(target_w or 0.0))
    nominal_w_per_amp = 230.0 * phase_count
    # Gemessene Minderabnahme beschreibt nur das Fahrzeugverhalten. Sie darf
    # niemals den elektrischen Wattdeckel öffnen: die Freigabe wird normativ
    # mit 230 V je aktiver Phase übersetzt.
    effective_w_per_amp = nominal_w_per_amp
    min_w = 6.0 * effective_w_per_amp
    if target < min_w:
        return 0, 0.0

    base_amp = max(6.0, min(float(max_amp), _round_amp_down_to_step(target / effective_w_per_amp, step)))
    assist_gap_w = 0.0
    if assist_allowed and base_amp < max_amp:
        next_amp = min(float(max_amp), _round_amp_up_to_step(base_amp + step, step))
        next_w = next_amp * effective_w_per_amp
        gap_w = max(0.0, next_w - target)
        max_gap_w = max(0.0, float(assist_max_gap_w or 0.0))
        if 0.0 < gap_w <= max_gap_w:
            return next_amp, gap_w
    return base_amp, assist_gap_w


def _openwb_pro_surplus_step(
    c_data,
    status,
    *,
    target_w,
    grid_w,
    phases,
    current_amp,
    charger_max_amp,
    marginal_actor=True,
    now_ts=None,
):
    """Führt den einzigen reinen openWB-Pro-Überschussreglervertrag aus."""

    data = c_data if isinstance(c_data, dict) else {}
    st = status if isinstance(status, dict) else {}
    charger = data.get("charger")
    step = _current_step_amp_for_charger(charger, default=0.1)
    actual_amp = max(
        _cfg_float(st.get("offered_current_raw"), 0.0),
        _cfg_float(st.get("evse_current"), 0.0),
        _cfg_float(st.get("amp"), 0.0),
    )
    last_command = data.get("_last_executed_command")
    last_command_amp = (
        _cfg_float(last_command.get("amp"), 0.0)
        if isinstance(last_command, dict)
        and str(last_command.get("method") or "") == "set_amp_and_state"
        else 0.0
    )
    command_confirmed = bool(
        last_command_amp <= 0.0
        or abs(actual_amp - last_command_amp) <= max(step * 1.5, 0.15)
        or _wb_status_real_power(st) > 500.0
    )
    transition = data.get("_wallbox_phase_transition_reservation")
    contract = wallbox_surplus_control.surplus_control_step(
        grid_w=grid_w,
        grant_w=target_w,
        current_amp=current_amp,
        actual_amp=actual_amp,
        phases=phases,
        current_step_amp=step,
        effective_w_per_amp=230.0 * max(1, int(phases or 1)),
        min_amp=6.0,
        max_amp=charger_max_amp,
        data_valid=bool(
            st.get("driver_status_valid", True)
            and not st.get("driver_status_stale", False)
        ),
        coherent=not bool(st.get("driver_status_glitch", False)),
        command_confirmed=command_confirmed,
        transition_active=bool(isinstance(transition, dict) and transition.get("active")),
        cp_active=bool(st.get("cp_interrupt_isactive", False)),
        heatpump_starting=bool(data.get("_heatpump_starting", False)),
        marginal_actor=marginal_actor,
        now_ts=time.time() if now_ts is None else float(now_ts),
        previous_state=data.get("_openwb_pro_surplus_state"),
        target_grid_w=_cfg_float(data.get("_surplus_target_grid_w"), -125.0),
        noise_w=_cfg_float(data.get("_surplus_noise_w"), 100.0),
        reaction_noise_w=_cfg_float(data.get("_surplus_reaction_noise_w"), 0.0),
        max_up_step_a=1.0,
        cycle_s=max(0.5, _cfg_float(data.get("_loop_sleep_s"), 2.0)),
    )

    data["_openwb_pro_surplus_state"] = dict(contract.get("state_patch") or {})
    data["_openwb_pro_surplus_contract"] = contract
    return contract


def _openwb_pro_phase_start_stop_contract(
    *,
    phase_switch_action,
    phase_wait_active,
    effective_current_amp,
    physically_chargeable,
    charger_connected,
    current_amp,
    current_set_amp,
    min_amp=6.0,
):
    """Projiziert START erst aus dem finalen physischen Stromdeckel."""

    min_val = max(0.0, _cfg_float(min_amp, 6.0))
    current_running_val = max(
        _cfg_float(current_amp, 0.0),
        _cfg_float(current_set_amp, 0.0),
    )
    is_running = bool(current_running_val + 0.001 >= min_val)

    if (
        bool(phase_wait_active)
        or not bool(physically_chargeable)
        or not bool(charger_connected)
    ):
        return {
            "action": "NOOP",
            "target_amp": 0.0,
            "hold_amp": 0.0,
            "reason": "phase_decision_pending_start_stop",
        }

    target_amp = max(0.0, _cfg_float(effective_current_amp, 0.0))
    if target_amp + 0.001 < min_val:
        if is_running and str(phase_switch_action or "") != "KEEP_PHASES":
            # HOLD_PHASE_RECOMMENDATION: Laufende Ladung bei ausstehender Phasenempfehlung mit sicherem Strom halten
            return {
                "action": "SET_CURRENT",
                "target_amp": current_running_val,
                "hold_amp": current_running_val,
                "reason": "phase_recommendation_pending_hold",
            }
        return {
            "action": "NOOP",
            "target_amp": 0.0,
            "hold_amp": 0.0,
            "reason": "phase_decision_pending_start_stop",
        }

    if str(phase_switch_action or "") != "KEEP_PHASES":
        if is_running:
            return {
                "action": "SET_CURRENT",
                "target_amp": target_amp,
                "hold_amp": target_amp,
                "reason": "phase_recommendation_pending_hold",
            }
        return {
            "action": "NOOP",
            "target_amp": 0.0,
            "hold_amp": 0.0,
            "reason": "phase_decision_pending_start_stop",
        }

    action = (
        "START"
        if not is_running
        else "SET_CURRENT"
    )
    return {
        "action": action,
        "target_amp": target_amp,
        "hold_amp": target_amp,
        "reason": "phase_decision_apply_current",
    }


def _openwb_pro_planned_cold_start_command(
    c_data,
    status,
    *,
    phase_switch_action="KEEP_PHASES",
    phase_wait_active=False,
    priority_forced_stop=False,
    manual_pause=False,
    locked=False,
    emergency_stop=False,
    charger_max_amp=32,
    now_ts=None,
):
    """Liefert genau den autorisierten 0→6-A-Startimpuls oder keinen Befehl."""

    data = c_data if isinstance(c_data, dict) else {}
    st = status if isinstance(status, dict) else {}
    planned = data.get("_driver_command")
    payload = data.get("_decision_payload")
    session = data.get("_openwb_pro_session")
    planned = planned if isinstance(planned, dict) else {}
    payload = payload if isinstance(payload, dict) else {}
    session = session if isinstance(session, dict) else {}
    mode = payload.get("mode") if isinstance(payload.get("mode"), dict) else {}
    decisions = payload.get("decisions") if isinstance(payload.get("decisions"), dict) else {}
    start_stop = decisions.get("start_stop") if isinstance(decisions.get("start_stop"), dict) else {}
    planned_kind = str(planned.get("method") or planned.get("kind") or "")
    planned_amp = _cfg_float(planned.get("amp"), 0.0)
    offered_amp = max(
        _cfg_float(st.get("offered_current_raw"), 0.0),
        _cfg_float(st.get("evse_current"), 0.0),
        _cfg_float(st.get("amp"), 0.0),
    )
    real_power_w = max(
        _cfg_float(st.get("real_power_w"), 0.0),
        _cfg_float(st.get("phase_power_sum_w"), 0.0),
        _cfg_float(st.get("power_w"), 0.0),
    )
    transition = data.get("_wallbox_phase_transition_reservation")
    phase_restart = _openwb_pro_phase_restart_current_contract(data, st)
    data["_openwb_pro_phase_restart_current_contract"] = phase_restart
    transition_blocks_start = bool(
        isinstance(transition, dict)
        and transition.get("active")
        and not phase_restart.get("authorized", False)
    )
    recovery = data.get("_openwb_pro_phase_recovery_hold")
    session_state = str(session.get("state") or data.get("_openwb_pro_session_state") or "")
    typed_anchor = (
        data.get("_manager_zero_anchor_contract")
        if isinstance(data.get("_manager_zero_anchor_contract"), dict)
        else {}
    )
    temporary_stop = (
        session.get("temporary_stop")
        if isinstance(session.get("temporary_stop"), dict)
        else {}
    )
    soft_until = _cfg_float(data.get("_openwb_start_reject_soft_until"), 0.0)
    own_elapsed_phase_restart_soft_stop = bool(
        phase_restart.get("authorized", False)
        and data.get("_manager_zero_anchor_active", False)
        and str(typed_anchor.get("contract") or "")
        == "wallbox_manager_zero_anchor_v1"
        and str(typed_anchor.get("owner") or "") == "wallbox_manager"
        and str(typed_anchor.get("reason_code") or "")
        == "vehicle_start_rejected_soft"
        and str(data.get("_bev_full_block_reason") or "")
        == "start_rejected_soft"
        and not bool(data.get("_bev_full_blocked", False))
        and soft_until > 0.0
        and (time.time() if now_ts is None else float(now_ts)) >= soft_until
        and session_state == "stopping"
        and str(
            session.get("temporary_stop_reason")
            or temporary_stop.get("reason")
            or ""
        )
        == "vehicle_start_rejected_soft"
    )
    eligible = bool(
        planned_kind in ("set_current", "set_amp_and_state", "set_direct_current")
        and str(planned.get("reason") or "") == "phase_decision_apply_current"
        and str(start_stop.get("action") or "") == "START"
        and int(mode.get("public", 0) or 0) > 0
        and planned_amp >= 6.0
        and offered_amp < 0.5
        and _cfg_float(data.get("current_set_amp"), 0.0) < 0.5
        and real_power_w <= 500.0
        and str(phase_switch_action or "") == "KEEP_PHASES"
        and not bool(phase_wait_active)
        and not bool(priority_forced_stop)
        and not bool(manual_pause)
        and not bool(locked)
        and not bool(emergency_stop)
        and bool(st.get("driver_status_valid", True))
        and not bool(st.get("driver_status_stale", False))
        and not bool(st.get("driver_status_glitch", False))
        and not bool(st.get("cp_interrupt_isactive", False))
        and not transition_blocks_start
        and not bool(isinstance(recovery, dict) and recovery.get("active"))
        and not bool(data.get("_bev_full_blocked", False))
        and (
            not bool(data.get("_manager_zero_anchor_active", False))
            or own_elapsed_phase_restart_soft_stop
        )
        and (
            not bool(session.get("start_blocked", False))
            or own_elapsed_phase_restart_soft_stop
        )
        and (
            bool(session.get("can_send_start_command", True))
            or own_elapsed_phase_restart_soft_stop
        )
        and session_state != "ended"
        and (session_state != "stopping" or own_elapsed_phase_restart_soft_stop)
    )
    if not eligible:
        return {}
    command = dict(planned)
    command["amp"] = min(6.0, planned_amp, float(charger_max_amp or 32))
    command["force_state"] = 2
    command["reason"] = "phase_decision_apply_current"
    if phase_restart.get("authorized", False):
        command["_openwb_pro_phase_restart_current"] = True
    return command


def _openwb_pro_direct_3p_cold_start_contract(
    status,
    *,
    openwb_pro=False,
    charger_connected=False,
    control_mode=0,
    public_mode=0,
    hw_charging=False,
    stable_hw_power_w=0.0,
    cap_amp=0,
    vehicle_max_phases=0,
    phase_3p_supported=False,
    phase_cap_phases=0,
    phase_target=0,
    phase_switch_phases=0,
    phase_wait_active=False,
    phase_block_active=False,
    transition_active=False,
    recovery_active=False,
    priority_forced_stop=False,
    vehicle_finished=False,
    manual_pause=False,
    locked=False,
    emergency_stop=False,
):
    """Bindet den unmittelbaren 3p-Kaltstart eines bekannten 3p-Fahrzeugs.

    Unbekannte oder 1p-Fahrzeuge bleiben im konservativen Strom-zuerst-Pfad.
    Nutzer-Aus, Safety, stale Daten, laufende Übergänge und CP-Unterbrechung
    bleiben harte Sperren.
    """

    st = status if isinstance(status, dict) else {}
    checks = {
        "openwb_pro": bool(openwb_pro),
        "connected": bool(
            charger_connected
            and (st.get("plug_state") is True or st.get("car") == 2)
        ),
        "fresh_status": bool(
            st.get("driver_status_valid", True)
            and not st.get("driver_status_stale", False)
            and not st.get("driver_status_degraded", False)
            and not st.get("driver_status_glitch", False)
        ),
        "cp_inactive": st.get("cp_interrupt_isactive") in (False, 0),
        "mode_enabled": int(control_mode or 0) > 0 and int(public_mode or 0) > 0,
        "idle": bool(
            not hw_charging
            and float(stable_hw_power_w or 0.0) <= 500.0
            # connect.php kann direkt nach dem Anstecken noch das initiale
            # 6-A-Angebot ausweisen, obwohl real kein Strom fließt. Das ist
            # für den bekannten 3p-Kaltstart zulässig, weil die Phasensequenz
            # vor phasetarget selbst zuerst auf 0 A setzt. Ein höheres Angebot
            # bleibt dagegen konservativ gesperrt.
            and (
                _fresh_wallbox_reported_current_amp(st) is None
                or _fresh_wallbox_reported_current_amp(st) <= 6.0
            )
        ),
        "known_3p_vehicle": int(vehicle_max_phases or 0) >= 3,
        "3p_supported": bool(
            phase_3p_supported and int(phase_cap_phases or 0) >= 3
        ),
        "positive_budget": float(cap_amp or 0.0) >= 6.0,
        "target_needs_3p": bool(
            int(phase_target or 0) != 3
            and int(phase_switch_phases or 0) in (0, 1)
        ),
        "no_phase_wait": not bool(phase_wait_active),
        "no_phase_block": not bool(phase_block_active),
        "no_active_transition": not bool(transition_active),
        "no_recovery": not bool(recovery_active),
        "no_priority_stop": not bool(priority_forced_stop),
        "vehicle_not_finished": not bool(vehicle_finished),
        "no_manual_pause": not bool(manual_pause),
        "not_locked": not bool(locked),
        "no_emergency_stop": not bool(emergency_stop),
    }
    blockers = [name for name, passed in checks.items() if not passed]
    return {
        "contract": "openwb_pro_direct_3p_cold_start_v1",
        "allow": not blockers,
        "target_phases": 3,
        "checks": checks,
        "blockers": blockers,
    }


def _phase_up_execution_wait_seconds(
    *,
    openwb_pro=False,
    direct_3p_cold_start=False,
    predump_wallbox_active=False,
    phase_forecast_hold_for_wb=False,
    phase_configured_3p=False,
    phase_3p_supported=False,
    phase_up_forecast_hold_s=0.0,
):
    """Bindet die Wartezeit des tatsächlich ausführenden Phasenpfads.

    Ein bereits fachlich und sicherheitlich freigegebener direkter 3p-Kaltstart
    darf im späteren Executor nicht erneut durch die allgemeine 1→3-Hysterese
    verzögert werden. Für alle übrigen openWB-Pro-Fälle bleibt diese Hysterese
    erhalten; unbekannte und 1p-Fahrzeuge werden damit weiter konservativ
    behandelt.
    """

    hold_s = max(0.0, float(phase_up_forecast_hold_s or 0.0))
    if openwb_pro:
        wait_s = 0.0 if direct_3p_cold_start else hold_s
    else:
        wait_s = 0.0 if predump_wallbox_active else 45.0
    if (
        phase_forecast_hold_for_wb
        and not phase_configured_3p
        and not (openwb_pro and phase_3p_supported)
    ):
        wait_s = max(wait_s, hold_s)
    return wait_s


def _openwb_pro_phase_restart_current_contract(c_data, status, *, now_ts=None):
    """Autorisiert genau den ersten 6-A-Neustart nach echtem Phasenwechsel.

    Die Phasenreservierung bleibt bis zur realen Ladebestätigung absichtlich
    aktiv. Ohne diese enge Ausnahme entstünde jedoch ein Zirkelschluss: Die
    Reservierung wartet auf Ladeleistung, während die Startausgabe wegen der
    aktiven Reservierung gesperrt bleibt. Freigegeben wird deshalb nur eine
    vollständig persistierte, bestätigte Phasengeneration nach der kurzen
    openWB-Gerätepause und bei frischem, ruhigem Ziel-Readback. Die 480 s
    sperren nur eine weitere Phasenumschaltung.
    """

    data = c_data if isinstance(c_data, dict) else {}
    st = status if isinstance(status, dict) else {}
    now_value = time.time() if now_ts is None else float(now_ts)
    reservation = data.get("_wallbox_phase_transition_reservation")
    restart = data.get("_openwb_pro_phase_restart_authorized")
    intent = data.get("_openwb_pro_phase_output_intent")
    ack = data.get("_openwb_pro_phase_output_ack")
    sequence = data.get("_openwb_pro_phase_sequence")
    reservation = reservation if isinstance(reservation, dict) else {}
    restart = restart if isinstance(restart, dict) else {}
    intent = intent if isinstance(intent, dict) else {}
    ack = ack if isinstance(ack, dict) else {}
    sequence = sequence if isinstance(sequence, dict) else {}
    recovery = data.get("_openwb_pro_phase_recovery_hold")
    recovery = recovery if isinstance(recovery, dict) else {}

    target = _valid_phase_count(reservation.get("target_phases"), 0)
    reservation_id = str(
        reservation.get("reservation_id")
        or reservation.get("transition_id")
        or ""
    )
    intent_id = str(intent.get("intent_id") or "")
    intent_transition_id = str(intent.get("transition_id") or "")
    deadline = _cfg_float(reservation.get("stage_deadline_ts"), 0.0)
    authorized_ts = _cfg_float(restart.get("authorized_ts"), 0.0)
    restart_phase_ts = _cfg_float(restart.get("phase_sent_ts"), 0.0)
    sequence_patch = intent.get("sequence_patch")
    sequence_patch = sequence_patch if isinstance(sequence_patch, dict) else {}
    intent_phase_ts = _cfg_float(sequence_patch.get("phase_sent_ts"), 0.0)
    same_phase_generation = bool(
        restart_phase_ts > 0.0
        and intent_phase_ts > 0.0
        and abs(restart_phase_ts - intent_phase_ts) <= 0.1
    )
    cp_inactive = st.get("cp_interrupt_isactive") in (False, 0)

    checks = {
        "reservation_active": bool(reservation.get("active")),
        "reservation_stage": str(reservation.get("stage") or "") in ("confirm_target", "recovery_hold"),
        "reservation_committed": bool(
            str(reservation.get("grant_state") or "") == "committed"
            and int(reservation.get("committed_w", 0) or 0)
            >= int(reservation.get("requested_w", 0) or 0)
        ),
        "reservation_id_bound": bool(
            reservation_id
            and str(reservation.get("reservation_id") or reservation_id)
            == reservation_id
            and str(reservation.get("transition_id") or reservation_id)
            == reservation_id
        ),
        "target_valid": target in (1, 3),
        "deadline_elapsed": bool(deadline > 0.0 and now_value >= deadline),
        "restart_bound": bool(
            restart.get("active") is True
            and _valid_phase_count(restart.get("target"), 0) == target
            and str(restart.get("source") or "")
            == "phase_target_settle_readback_confirmed"
            and authorized_ts >= deadline > 0.0
        ),
        "output_intent_bound": bool(
            intent_id.startswith(reservation_id + ":send_phase:")
            and (
                not intent_transition_id
                or intent_transition_id == reservation_id
            )
            and str(intent.get("action") or "") == "send_phase"
            and str(intent.get("method") or "") == "set_phases"
            and _valid_phase_count(intent.get("target"), 0) == target
        ),
        "output_ack_bound": bool(
            ack.get("success") is True
            and str(ack.get("intent_id") or "")
            and str(ack.get("intent_id") or "") == str(intent.get("intent_id") or "")
        ),
        "same_phase_generation": same_phase_generation,
        "sequence_terminal": not bool(sequence),
        "recovery_clear": not bool(recovery.get("active", False)),
        "cp_inactive": cp_inactive,
        "fresh_status": bool(
            st.get("driver_status_valid") is True
            and st.get("driver_status_stale") is not True
            and st.get("driver_status_degraded") is not True
            and st.get("driver_status_glitch") is not True
            and st.get("driver_status_plausible") is not False
        ),
        "fresh_target_confirmed": bool(
            target in (1, 3)
            and openwb_pro_session.phase_target_readback_confirmed(st, target)
        ),
    }
    blockers = [name for name, passed in checks.items() if not passed]
    return {
        "contract": "openwb_pro_phase_restart_current_v1",
        "authorized": not blockers,
        "target": target,
        "deadline_ts": deadline,
        "authorized_ts": authorized_ts,
        "checks": checks,
        "blockers": blockers,
    }


def _openwb_pro_one_phase_user_limit(config, charger_id=None):
    cfg = config or {}
    keys = []
    try:
        cid = int(charger_id or 0)
    except (TypeError, ValueError):
        cid = 0
    if cid > 0:
        keys.extend((
            f"wb{cid}_openwb_pro_1p_max_amp",
            f"wb{cid}_one_phase_max_amp",
        ))
    keys.extend((
        "openwb_pro_1p_max_amp",
        "wb_one_phase_max_amp",
        "wallbox_one_phase_max_amp",
    ))
    raw = None
    for key in keys:
        value = cfg.get(key)
        if value is not None and str(value).strip() != "":
            return value
    return None


def _phase_config_vector(config, key_prefix):
    cfg = config if isinstance(config, dict) else {}
    return tuple(cfg.get(f"{key_prefix}_l{phase}") for phase in (1, 2, 3))


def _phase_operating_limit_vector(config, scalar_grid_limit=None):
    cfg = config if isinstance(config, dict) else {}
    grid_fallback = cfg.get("grid_max_amps", scalar_grid_limit)
    reserve_fallback = cfg.get("grid_wallbox_reserve_amps", 2.0)
    limits = []
    for phase in (1, 2, 3):
        grid_raw = cfg.get(f"grid_max_amps_l{phase}")
        if grid_raw is None or str(grid_raw).strip() == "":
            grid_raw = grid_fallback
        reserve_raw = cfg.get(f"grid_wallbox_reserve_amps_l{phase}")
        if reserve_raw is None or str(reserve_raw).strip() == "":
            reserve_raw = reserve_fallback
        try:
            grid_value = float(grid_raw)
            reserve_value = float(reserve_raw)
        except (TypeError, ValueError):
            return None
        if (
            not math.isfinite(grid_value)
            or not math.isfinite(reserve_value)
            or grid_value <= 0.0
            or reserve_value < 0.0
            or reserve_value >= grid_value
        ):
            return None
        limits.append(grid_value - reserve_value)
    return tuple(limits)


def _openwb_pro_one_phase_max_amp(config, charger_id=None, charger_max_amp=16):
    raw = _openwb_pro_one_phase_user_limit(config, charger_id)
    try:
        configured = float(raw if raw is not None else 20.0)
    except (TypeError, ValueError):
        configured = 20.0
    try:
        wallbox_max = float(charger_max_amp or 16)
    except (TypeError, ValueError):
        wallbox_max = 16.0
    return max(6.0, min(max(6.0, wallbox_max), max(6.0, configured)))


def _openwb_pro_accepted_phase_amp(status):
    """Liefere den tatsächlich gemessenen höchsten Phasenstrom.

    Ein angebotener Sollstrom (``amp``/``offered_current_raw``) ist kein
    belastbarer Iststrom und darf deshalb keinen zusätzlichen PCC-Headroom
    freigeben. Explizite 0-A-Phasenwerte sind dagegen eine gültige Messung,
    solange der Treiberstatus frisch und plausibel ist.
    """

    st = status if isinstance(status, dict) else {}
    status_fresh = bool(
        st.get("driver_status_valid") is True
        and st.get("driver_status_stale") is False
        and not bool(st.get("stale", False))
        and not bool(st.get("driver_status_glitch", False))
    )
    if not status_fresh:
        return 0.0, False

    measured = []
    measurement_present = False
    for phase in (1, 2, 3):
        current_key = f"phase_current_l{phase}_a"
        power_key = f"phase_power_l{phase}_w"
        current_present = current_key in st and st.get(current_key) is not None
        power_present = power_key in st and st.get(power_key) is not None
        measurement_present = measurement_present or current_present or power_present
        if current_present:
            try:
                value = float(st.get(current_key))
            except (TypeError, ValueError):
                return 0.0, False
            if not math.isfinite(value) or value < 0.0:
                return 0.0, False
            measured.append(value)
            continue
        if power_present:
            try:
                power_w = float(st.get(power_key))
            except (TypeError, ValueError):
                return 0.0, False
            if not math.isfinite(power_w):
                return 0.0, False
            measured.append(abs(power_w) / 230.0)
            continue
        measured.append(0.0)

    if not measurement_present:
        return 0.0, False
    return max(measured or [0.0]), True


def _cap_openwb_pro_one_phase_amp(
    amp,
    phases,
    config,
    charger_id=None,
    charger_max_amp=16,
    *,
    live=None,
    live_data_fresh=False,
    live_sample_invalid=True,
    charger_status=None,
    c_data=None,
    grid_max_amps=None,
):
    try:
        phase_count = int(phases or 1)
    except (TypeError, ValueError):
        phase_count = 1
    try:
        value = float(amp or 0.0)
    except (TypeError, ValueError):
        value = 0.0
    if phase_count <= 1 and value > 0.0:
        static_cap = _openwb_pro_one_phase_max_amp(
            config,
            charger_id,
            charger_max_amp,
        )
        if not isinstance(live, dict):
            return min(value, static_cap)

        cfg = config or {}
        cid = int(charger_id or 1)
        measured_pcc_a = _pcc_phase_current_estimate(live)
        accepted_amp, accepted_fresh = _openwb_pro_accepted_phase_amp(
            charger_status
        )
        reserve_raw = cfg.get("grid_wallbox_reserve_amps", 2.0)
        contract = wallbox_phase_balancing.openwb_pro_one_phase_current_cap(
            user_limit_a=_openwb_pro_one_phase_user_limit(cfg, cid),
            charger_limit_a=charger_max_amp,
            grid_max_amps=(
                grid_max_amps
                if grid_max_amps is not None
                else cfg.get("grid_max_amps")
            ),
            grid_max_phase_amps=_phase_config_vector(
                cfg,
                "grid_max_amps",
            ),
            reserve_a=reserve_raw,
            reserve_phase_amps=_phase_config_vector(
                cfg,
                "grid_wallbox_reserve_amps",
            ),
            measured_pcc_a=measured_pcc_a,
            data_valid=bool(
                measured_pcc_a is not None
                and live_sample_invalid is False
            ),
            data_fresh=bool(live_data_fresh),
            hard_rms_current_measurement=False,
            grid_phase=cfg.get(
                f"wb{cid}_grid_phase",
                cfg.get(f"wb{cid}_phase"),
            ),
            phase_rotation=cfg.get(
                f"wb{cid}_grid_phase_rotation",
                cfg.get(f"wb{cid}_phase_rotation"),
            ),
            accepted_amp=accepted_amp,
            accepted_measurement_fresh=accepted_fresh,
            fallback_cap_a=20.0,
            min_amp=6.0,
            require_phase_specific_grid_limit=True,
        )
        contract["requested_amp"] = value
        contract["applied_amp"] = min(value, float(contract["cap_amp"]))
        contract["active"] = True
        contract["charger_phases"] = 1
        contract["measurement_basis"] = "pcc_phase_active_power_div_230v"
        contract["hard_rms_current_measurement"] = False
        if isinstance(c_data, dict):
            contract["cycle_token"] = c_data.get("_wallbox_cycle_token")
            c_data["_openwb_pro_one_phase_cap"] = contract
        return contract["applied_amp"]
    return value


def _charger_max_amp(config, charger_id, fallback_amp=16, status=None):
    """Liefere ausschließlich die Infrastrukturgrenze des Ladepunkts.

    Fahrzeugprofile sind phasenabhängig und werden erst nach der wirksamen
    Phasenwahl über den sitzungsgebundenen OBC-Vertrag angewendet.
    """
    cid = int(charger_id or 1)
    configured_amp = None
    for key in (f"wb{cid}_max_amp", f"wb{cid}_maxladestrom"):
        raw = (config or {}).get(key)
        if raw is not None and str(raw).strip() != "":
            configured_amp = _amp_limit(raw, fallback_amp)
            break
    if configured_amp is None:
        configured_amp = _amp_limit(fallback_amp, 16)
    return max(0, int(configured_amp))

def _wb_cfg_float(config, charger_id, key, default=0.0, minimum=None, maximum=None):
    """Read a wallbox timing value with wb1_/wb2_ override and global fallback."""
    cfg = config or {}
    cid = int(charger_id or 1)
    raw = cfg.get(f"wb{cid}_{key}")
    if raw is None or str(raw).strip() == "":
        raw = cfg.get(f"wb_{key}", cfg.get(key, default))
    value = _cfg_float(raw, default)
    if minimum is not None:
        value = max(float(minimum), value)
    if maximum is not None:
        value = min(float(maximum), value)
    return value

